+      </Link>
+      <form action={revalidateTemplateSeed}>
+        <button type="submit" id="template-seed-revalidate">
+          Revalidate
+        </button>
+      </form>
+    </div>
+  );
+}
+
+export function generateStaticParams() {
+  return [{ section: "x" }, { section: "y" }];
+}
